\begin{array}{l}
\mathrm{Al}_{2} \mathrm{O}_{3}+6 \mathrm{HCl} \rightarrow 2 \mathrm{Al} \mathrm{Cl}_{3}+3 \mathrm{H}_{2} \mathrm{O} \\
\mathrm{Al}_{2} \mathrm{O}_{3}+2 \mathrm{NaOH} \rightarrow 2 \mathrm{NaAlO}_{2}+\mathrm{H}_{2} \mathrm{O}
\end{array}
\]

